    async def list_pools(
        self,
        *,
        cluster_id: str,
        region: str | None = None,
        order_by: ListPoolsRequestOrderBy | None = None,
        page: int | None = None,
        page_size: int | None = None,
        name: str | None = None,
        status: PoolStatus | None = None,
    ) -> ListPoolsResponse:
        """
        List Pools in a Cluster

        List all the existing pools for a specific Kubernetes cluster.

        Args:
            region: The region you want to target
            cluster_id: ID of the cluster whose pools will be listed.
            order_by: Sort order of returned pools.
            page: Page number for the returned pools.
            page_size: Maximum number of pools per page.
            name: Name to filter on, only pools containing this substring in their name
                will be returned.
            status: Status to filter on, only pools with this status will be returned.
        """
        data = await self._client.request_json(
            "GET",
            self._client.path(
                "/k8s/v1/regions/{region}/clusters/{cluster_id}/pools",
                region=self._client.region(region),
                cluster_id=cluster_id,
            ),
            params={
                "order_by": order_by,
                "page": page,
                "page_size": page_size,
                "name": name,
                "status": status,
            },
        )
        return ListPoolsResponse.model_validate(data)

    async def list_pools_iter(
        self,
        *,
        cluster_id: str,
        region: str | None = None,
        order_by: ListPoolsRequestOrderBy | None = None,
        page_size: int | None = None,
        name: str | None = None,
        status: PoolStatus | None = None,
    ) -> AsyncIterator[Pool]:
        """Iterate over every item of `list_pools`, page after page."""

        async def fetch(page: int) -> tuple[ListPoolsResponse, int | None]:
            response = await self._client.request(
                "GET",
                self._client.path(
                    "/k8s/v1/regions/{region}/clusters/{cluster_id}/pools",
                    region=self._client.region(region),
                    cluster_id=cluster_id,
                ),
                params={
                    "order_by": order_by,
                    "page": page,
                    "page_size": page_size,
                    "name": name,
                    "status": status,
                },
            )
            result = ListPoolsResponse.model_validate(response.json())
            return result, result.total_count

        async for entry in paginate(
            fetch,
            lambda page: page[0].pools or [],
            lambda page: page[1],
        ):
            yield entry

    async def list_pools_all(
        self,
        *,
        cluster_id: str,
        region: str | None = None,
        order_by: ListPoolsRequestOrderBy | None = None,
        page_size: int | None = None,
        name: str | None = None,
        status: PoolStatus | None = None,
    ) -> list[Pool]:
        """Every item of `list_pools`, all pages read."""
        return [
            entry
            async for entry in self.list_pools_iter(
                cluster_id=cluster_id,
                region=region,
                order_by=order_by,
                page_size=page_size,
                name=name,
                status=status,
            )
        ]

    async def create_pool(
        self,
        *,
        cluster_id: str,
        name: str,
        node_type: str,
        size: int,
        region: str | None = None,
        placement_group_id: str | None = None,
        autoscaling: bool | None = None,
        min_size: int | None = None,
        max_size: int | None = None,
        container_runtime: Runtime | None = None,
        autohealing: bool | None = None,
        tags: list[str] | None = None,
        kubelet_args: dict[str, str] | None = None,
        upgrade_policy: CreatePoolRequestUpgradePolicy | None = None,
        zone: str | None = None,
        root_volume_type: PoolVolumeType | None = None,
        root_volume_size: int | None = None,
        public_ip_disabled: bool | None = None,
        security_group_id: str | None = None,
        labels: dict[str, str] | None = None,
        taints: list[CoreV1Taint] | None = None,
        startup_taints: list[CoreV1Taint] | None = None,
        private_network_id: str | None = None,
        user_data: dict[str, str] | None = None,
        max_termination_grace_period: str | None = None,
    ) -> Pool:
        """
        Create a new Pool in a Cluster

        Create a new pool in a specific Kubernetes cluster.

        Args:
            region: The region you want to target
            cluster_id: Cluster ID to which the pool will be attached.
            name: Pool name.
            node_type: Node type is the type of Scaleway Instance wanted for the pool.
                Nodes with insufficient memory are not eligible (DEV1-S, PLAY2-PICO,
                STARDUST). 'external' is a special node type used to provision instances
                from other cloud providers in a Kosmos Cluster.
            placement_group_id: Placement group ID in which all the nodes of the pool
                will be created, placement groups are limited to 20 instances.
            autoscaling: Defines whether the autoscaling feature is enabled for the
                pool.
            size: Size (number of nodes) of the pool.
            min_size: Defines the minimum size of the pool. Note that this field is only
                used when autoscaling is enabled on the pool.
            max_size: Defines the maximum size of the pool. Note that this field is only
                used when autoscaling is enabled on the pool.
            container_runtime: Customization of the container runtime is available for
                each pool.
            autohealing: Defines whether the autohealing feature is enabled for the
                pool.
            tags: Tags associated with the pool, see [managing
                tags](https://www.scaleway.com/en/docs/kubernetes/api-cli/managing-
                tags).
            kubelet_args: Kubelet arguments to be used by this pool. Note that this
                feature is experimental.
            upgrade_policy: Defines how node provisioning should behave during pool
                version upgrade.
            zone: Zone in which the pool's nodes will be spawned.
            root_volume_type: Defines the system volume disk type. Several types of
                volume (`volume_type`) are provided:. * `l_ssd` is a local block storage
                which means your system is stored locally on your node's hypervisor.
                This type is not available for all node types * `sbs_5k` is a remote
                block storage which means your system is stored on a centralized and
                resilient cluster with 5k IOPS limits * `sbs_15k` is a faster remote
                block storage which means your system is stored on a centralized and
                resilient cluster with 15k IOPS limits * `b_ssd` is the legacy remote
                block storage which means your system is stored on a centralized and
                resilient cluster. Not available for new pools, use `sbs_5k` or
                `sbs_15k` instead.
            root_volume_size: System volume disk size. (in bytes)
            public_ip_disabled: Defines if the public IP should be removed from Nodes.
                To use this feature, your Cluster must have an attached Private Network
                set up with a Public Gateway.
            security_group_id: Security group ID in which all the nodes of the pool will
                be created. If unset, the pool will use default Kapsule security group
                in current zone.
            labels: Kubernetes labels applied and reconciled on the nodes.
            taints: Kubernetes taints applied and reconciled on the nodes.
            startup_taints: Kubernetes taints applied at node creation but not
                reconciled afterwards.
            private_network_id: Private network where the nodes are attached. Should be
                member of the same VPC as the API Server.
            user_data: User data applied and reconciled with the pool.
            max_termination_grace_period: Maximum amount of time in seconds before the
                API forces the drain and deletion of a `deleting` node. It overrides
                pods `PodDisruptionBudget` and `terminationGracePeriodSeconds`. Defaults
                to 15 minutes, up to 1 hour. (in seconds)
        """
        data = await self._client.request_json(
            "POST",
            self._client.path(
                "/k8s/v1/regions/{region}/clusters/{cluster_id}/pools",
                region=self._client.region(region),
                cluster_id=cluster_id,
            ),
            body={
                "name": name,
                "node_type": node_type,
                "placement_group_id": placement_group_id,
                "autoscaling": autoscaling,
                "size": size,
                "min_size": min_size,
                "max_size": max_size,
                "container_runtime": container_runtime,
                "autohealing": autohealing,
                "tags": tags,
                "kubelet_args": kubelet_args,
                "upgrade_policy": upgrade_policy,
                "zone": zone,
                "root_volume_type": root_volume_type,
                "root_volume_size": root_volume_size,
                "public_ip_disabled": public_ip_disabled,
                "security_group_id": security_group_id,
                "labels": labels,
                "taints": taints,
                "startup_taints": startup_taints,
                "private_network_id": private_network_id,
                "user_data": user_data,
                "max_termination_grace_period": max_termination_grace_period,
            },
        )
        return Pool.model_validate(data)

