    async def upgrade_cluster(
        self,
        *,
        cluster_id: str,
        version: str,
        region: str | None = None,
        upgrade_pools: bool | None = None,
    ) -> Cluster:
        """
        Upgrade a Cluster

        Upgrade a specific Kubernetes cluster and possibly its associated pools to a
        specific and supported Kubernetes version.

        Args:
            region: The region you want to target
            cluster_id: ID of the cluster to upgrade.
            version: New Kubernetes version of the cluster. Note that the version should
                either be a higher patch version of the same minor version or the direct
                minor version after the current one.
            upgrade_pools: Defines whether pools will also be upgraded once the control
                plane is upgraded.
        """
        data = await self._client.request_json(
            "POST",
            self._client.path(
                "/k8s/v1/regions/{region}/clusters/{cluster_id}/upgrade",
                region=self._client.region(region),
                cluster_id=cluster_id,
            ),
            body={"version": version, "upgrade_pools": upgrade_pools},
        )
        return Cluster.model_validate(data)

