    async def update_pool(
        self,
        *,
        pool_id: str,
        region: str | None = None,
        autoscaling: bool | None = None,
        size: int | None = None,
        min_size: int | None = None,
        max_size: int | None = None,
        autohealing: bool | None = None,
        tags: list[Any] | None = None,
        kubelet_args: dict[str, str] | None = None,
        upgrade_policy: UpdatePoolRequestUpgradePolicy | None = None,
        security_group_id: str | None = None,
        max_termination_grace_period: str | None = None,
    ) -> Pool:
        """
        Update a Pool in a Cluster

        Update the attributes of a specific pool, such as its desired size, autoscaling
        settings, and tags. To upgrade a pool, you will need to use the dedicated
        endpoint.

        Args:
            region: The region you want to target
            pool_id: ID of the pool to update.
            autoscaling: New value for the pool autoscaling enablement.
            size: New desired pool size.
            min_size: New minimum size for the pool.
            max_size: New maximum size for the pool.
            autohealing: New value for the pool autohealing enablement.
            tags: New tags associated with the pool.
            kubelet_args: New Kubelet arguments to be used by this pool. Note that this
                feature is experimental.
            upgrade_policy: New upgrade policy for the pool.
            security_group_id: Security group ID in which all the nodes of the pool will
                be moved.
            max_termination_grace_period: New maximum amount of time in seconds before
                the API forces the drain and deletion of a `deleting` node. (in seconds)
        """
        data = await self._client.request_json(
            "PATCH",
            self._client.path(
                "/k8s/v1/regions/{region}/pools/{pool_id}",
                region=self._client.region(region),
                pool_id=pool_id,
            ),
            body={
                "autoscaling": autoscaling,
                "size": size,
                "min_size": min_size,
                "max_size": max_size,
                "autohealing": autohealing,
                "tags": tags,
                "kubelet_args": kubelet_args,
                "upgrade_policy": upgrade_policy,
                "security_group_id": security_group_id,
                "max_termination_grace_period": max_termination_grace_period,
            },
        )
        return Pool.model_validate(data)

